stage_map = {"ex3":"A","ex4":"B","ex5":"C","ex6":"D","ex7":"E"}
for stage, key in stage_map.items():
    cases=[]
    for row in F:
        q, options, correct, critical = row[key]
        cases.append({
            "caseId": f"{stage.upper()}-{row['id']}",
            "familyId": row["id"],
            "sourceScope": row["source"],
            "question": q,
            "options": options,
            "oracleDecision": correct,
            "criticalUnsafeOptions": critical,
            "compactExplanation": row["law"],
            "questionScaffold": "Ask only what is uncertain: what happened; who can prove it; who decides what it means; who owns durable semantic state; who merely carries/executes; what does this evidence NOT prove; what breaks under deletion/intervention?",
            "typedRelations": row["relations"],
            "causalCard": row["card"],
        })
    corpus={"schemaVersion":1,"kind":"ordivon.ex3-ex7-causal-action-corpus","stage":stage,"frozenBeforeLiveCalls":True,"cases":cases}
    dump(f"{stage}-corpus-v1.json", corpus)

